    "pluginEntities": {
      "title": "Définition et Gestion des Versions de Plugins",
      "description": "PluginDefinition et PluginVersion : les deux entités racines régissant l'identité et les versions d'un plugin.",
      "intro": "Every plugin in the SCRIPE ecosystem starts with a PluginDefinition — the immutable identity record. Versions are snapshotted releases of that definition. Together they form the foundation that installations, API keys, and data stores build upon.",
      "definitionTitle": "Définition et Gestion des Versions de Plugins — PluginDefinition Entity",
      "definitionIntro": "Core entity representing a registered plugin in the platform. Contains metadata (name, description, icon), configuration (manifest, tier, scope), and developer association. Supports both Tier 1 (embedded .NET assembly) and Tier 2 (external HTTP service) plugin architectures.",
      "definitionNote": "Tier 1 plugins use AssemblyName + EntryPointType to locate the .NET class loaded into the host process. Tier 2 plugins use BaseUrl + FrontendUrl + WebhookUrl to communicate with an external service. Fields for the other tier are left null.",
      "codeTitle": "Définition et Gestion des Versions de Plugins — Entity Source",
      "versionTitle": "Définition et Gestion des Versions de Plugins — PluginVersion Entity",
      "versionIntro": "Represents a specific release version of a PluginDefinition. Tracks version number, bilingual release notes, manifest snapshot, and whether this is the latest active version. Each installation pins to a specific version at install time.",
      "versionLifecycleTitle": "Définition et Gestion des Versions de Plugins — Version Lifecycle",
      "versionLifecycleIntro": "When a new version is published, it becomes IsLatest = true and the previous version is demoted to IsLatest = false. Existing installations remain pinned to their installed version until an admin explicitly runs the upgrade command."
    },
    "pluginInstallation": {
      "title": "Installation et Sécurité des Plugins",
      "description": "PluginInstallation, PluginApiKey et PluginPermissionGrant pour le déploiement et la gestion des permissions.",
      "intro": "When a tenant installs a plugin, three core entities are created: a PluginInstallation record tracking deployment state, a PluginApiKey for secure plugin-to-platform API calls, and PluginPermissionGrant records for each platform capability the plugin is allowed to access.",
      "installationTitle": "Installation et Sécurité des Plugins — PluginInstallation Entity",
      "installationIntro": "Represents a tenant's installation of a specific PluginDefinition at a particular PluginVersion. A tenant can install the same plugin only once — enforced by a unique constraint on (TenantId + PluginDefinitionId).",
      "installationNote": "ConsecutiveHealthCheckFails is incremented by the plugins-health-check background job on each failed check and reset to 0 when the health check passes again. The Status is automatically transitioned to Error after a configurable failure threshold.",
      "lifecycleTitle": "Installation et Sécurité des Plugins — Installation Lifecycle",
      "lifecycleIntro": "A PluginInstallation starts in Installing status while the platform provisions resources, then transitions to Active. Admins can deactivate/reactivate it. Persistent health-check failures move it to Error.",
      "apiKeyTitle": "Installation et Sécurité des Plugins — PluginApiKey Entity",
      "apiKeyIntro": "Represents an API key issued to a plugin installation for authenticating plugin-to-platform API calls. Stores the hashed key value, a human-readable prefix for identification, activation status, and optional expiration.",
      "apiKeyWarning": "The raw API key value is shown only once at creation time and is never stored — only the hash is persisted. Plugins must store the key securely in their own secrets management system.",
      "permGrantTitle": "Installation et Sécurité des Plugins — PluginPermissionGrant Entity",
      "permGrantIntro": "Records an explicit permission grant to a plugin installation within a tenant. Each grant authorizes the plugin to access a specific platform capability. Platform admins must explicitly approve each permission during the installation setup wizard."
    },
    "pluginRuntime": {
      "title": "Exécution et Données des Plugins",
      "description": "PluginDataStore, PluginExecutionLog et PluginWebhookSubscription pour le stockage et l'audit d'exécution.",
      "intro": "Once a plugin is installed and active, three runtime entities handle its ongoing operation: PluginDataStore for persisting plugin state, PluginExecutionLog for monitoring API call health, and PluginWebhookSubscription for receiving platform events.",
      "dataStoreTitle": "Exécution et Données des Plugins — PluginDataStore Entity",
      "dataStoreIntro": "Key-value data store entry scoped to a plugin installation and tenant. Plugins use this to persist arbitrary JSON data organized by namespace and key. Tracks the serialized size for quota enforcement.",
      "dataStoreNote": "Data isolation is enforced at two levels: the unique constraint on (PluginInstallationId + TenantId + Namespace + Key) prevents collisions, and TenantId is always required to prevent cross-tenant data leakage. Plugins cannot read another tenant's data store entries.",
      "execLogTitle": "Exécution et Données des Plugins — PluginExecutionLog Entity",
      "execLogIntro": "Immutable audit log entry recording a single plugin API execution. Captures the HTTP method, endpoint, response status code, duration in milliseconds, and success/failure status. Used for monitoring plugin health and debugging.",
      "execLogTip": "The plugins-health-check background job queries PluginExecutionLog to compute ConsecutiveHealthCheckFails and update HealthCheckPassing on PluginInstallation. High DurationMs values are flagged as performance warnings.",
      "webhookTitle": "PluginWebhookSubscription Entity",
      "webhookIntro": "Represents a webhook subscription registered by a plugin installation. When the specified platform event type fires, the system dispatches an HTTP POST to the callback URL. Subscriptions can be deactivated (IsActive=false) without deletion.",
      "webhookFlowTitle": "Exécution et Données des Plugins — Webhook Delivery Flow",
      "webhookFlowIntro": "The platform uses an outbox pattern for reliable webhook delivery. Events are first written to the outbox, then delivered asynchronously to the plugin's CallbackUrl with exponential backoff retries."
    },
